package com.example.ems.web;
import com.example.ems.security.*;import com.example.ems.service.SessionService;import com.example.ems.model.SessionUser;
import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;import org.springframework.ui.Model;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import jakarta.servlet.http.*;import java.util.*;
@Controller public class SecurityController {
 private final SecurityService security;private final SecurityEvents events;private final SessionService sessions;private final JdbcTemplate jdbc;private final AttemptLimiter limiter;
 public SecurityController(SecurityService security,SecurityEvents events,SessionService sessions,JdbcTemplate jdbc,AttemptLimiter limiter){this.security=security;this.events=events;this.sessions=sessions;this.jdbc=jdbc;this.limiter=limiter;}
 private SessionUser user(HttpSession session){Object u;try{u=session.getAttribute("user");}catch(IllegalStateException closed){throw new SessionService.SessionExpired();}if(!(u instanceof SessionUser actor))throw new SessionService.SessionExpired();return actor;}
 private SessionUser executive(HttpSession s){var actor=user(s);if(!actor.isExecutive())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"只有高层可执行此操作");return actor;}
 private Map<String,Object> ok(Object data){var m=new LinkedHashMap<String,Object>();m.put("code",0);m.put("msg","操作成功");m.put("data",data);return m;}
 @ModelAttribute public void noCache(HttpServletResponse response){response.setHeader("Cache-Control","no-store");response.setHeader("Referrer-Policy","no-referrer");}
 @GetMapping("/security") public String page(HttpSession session,Model model){model.addAttribute("security",security.overview(user(session)));return "security";}
 @GetMapping("/security/reset") public String resetPage(){return "security-reset";}
 @PostMapping("/api/security/reset") @ResponseBody public Map<String,Object> reset(@RequestParam String employeeNo,@RequestParam String code,@RequestParam String password,@RequestParam String confirmPassword,HttpServletRequest request){limiter.check("reset:"+request.getRemoteAddr());if(!password.equals(confirmPassword))throw new IllegalArgumentException("两次密码不一致");security.selfReset(employeeNo,code,password);return ok(null);}
 @GetMapping("/security/temporary-password") public String temporaryPage(){return "security-temporary";}
 @PostMapping("/api/security/temporary-password") @ResponseBody public Map<String,Object> temporary(@RequestParam String password,@RequestParam String confirmPassword,HttpSession session){if(!password.equals(confirmPassword))throw new IllegalArgumentException("两次密码不一致");Long id=user(session).id();String observed=SessionService.token(session);security.temporaryPassword(id,password);SessionService.invalidateObserved(session,id,observed);return ok(null);}
 @PostMapping("/api/security/secondary") @ResponseBody public Map<String,Object> secondary(@RequestParam(defaultValue="") String loginPassword,@RequestParam(defaultValue="") String oldSecondary,@RequestParam String password,@RequestParam String confirmPassword,HttpSession session){if(!password.equals(confirmPassword))throw new IllegalArgumentException("两次密码不一致");limiter.check("secondary:"+user(session).id());security.secondary(executive(session).id(),loginPassword,oldSecondary,password);return ok(null);}
 @PostMapping("/api/security/authorize") @ResponseBody public Map<String,Object> authorize(@RequestParam Long target,@RequestParam String action,@RequestParam String password,HttpSession session){return ok(Map.of("grant",security.authorize(executive(session).id(),target,action,password)));}
 @PostMapping("/api/security/requests") @ResponseBody public Map<String,Object> request(@RequestParam String reason,HttpSession session){security.request(user(session).id(),reason);return ok(null);}
 @PostMapping("/api/security/requests/{id}/cancel") @ResponseBody public Map<String,Object> cancel(@PathVariable Long id,HttpSession session){security.cancel(user(session).id(),id);return ok(null);}
 @PostMapping("/api/security/requests/{id}/approve") @ResponseBody public Map<String,Object> approve(@PathVariable Long id,@RequestParam boolean approve,HttpSession session){String code=security.approve(executive(session).id(),id,approve);return ok(code==null?null:Map.of("secret",code,"label","重置码（30分钟有效，仅此次展示，请线下交付）"));}
 @PostMapping("/api/security/requests/{id}/reissue") @ResponseBody public Map<String,Object> reissue(@PathVariable Long id,HttpSession session){return ok(Map.of("secret",security.reissue(executive(session).id(),id),"label","重新签发的重置码（30分钟有效，旧码已失效）"));}
 @PostMapping("/api/security/accounts/{id}/reset") @ResponseBody public Map<String,Object> force(@PathVariable Long id,@RequestParam String grant,HttpSession session){return ok(Map.of("secret",security.forceReset(executive(session).id(),id,grant),"label","临时密码（24小时有效，仅此次展示，请线下交付）"));}
 @PostMapping("/api/security/accounts/{id}/unfreeze") @ResponseBody public Map<String,Object> unfreeze(@PathVariable Long id,@RequestParam String grant,@RequestParam String reason,HttpSession session){security.unfreeze(executive(session).id(),id,grant,reason);return ok(null);}
 @GetMapping("/api/security/notifications") @ResponseBody public Map<String,Object> notices(@RequestParam(required=false) String type,@RequestParam(required=false) String query,@RequestParam(required=false) String from,@RequestParam(required=false) String until,@RequestParam(required=false) String unread,HttpSession session){return ok(security.notifications(user(session).id(),type,query,from,until,unread));}
 @PostMapping("/api/security/notifications/{id}/read") @ResponseBody public Map<String,Object> read(@PathVariable Long id,HttpSession session){security.read(user(session).id(),id);return ok(null);}
 @GetMapping(value="/api/security/events",produces="text/event-stream") @ResponseBody public SseEmitter events(HttpSession session,HttpServletRequest request){var emitter=events.subscribe(user(session).id(),SessionService.digest(SessionService.token(session)));request.setAttribute("ems.sse.authorized",true);return emitter;}
 @GetMapping("/api/security/session-status") @ResponseBody public Map<String,Object> status(HttpServletRequest request,HttpServletResponse response){var s=request.getSession(false);if(s==null||!(s.getAttribute("user") instanceof SessionUser actor)){response.setStatus(401);return Map.of("code",401,"msg","登录已失效","data",Map.of("valid",false));}String token=SessionService.token(s);boolean valid=sessions.validate(actor.id(),token)==SessionService.Validity.VALID;var rows=jdbc.queryForList("SELECT a.account_status,e.employment_status,COALESCE(x.frozen,0) frozen,COALESCE(x.temporary_state,'NORMAL') temporary_state FROM user_account a JOIN employee e ON e.id=a.employee_id LEFT JOIN account_security x ON x.employee_id=e.id WHERE e.id=?",actor.id());valid=valid&&!rows.isEmpty()&&((Number)rows.get(0).get("account_status")).intValue()==1&&((Number)rows.get(0).get("employment_status")).intValue()==1&&((Number)rows.get(0).get("frozen")).intValue()==0&&"NORMAL".equals(rows.get(0).get("temporary_state"));if(valid)return ok(Map.of("valid",true));response.setStatus(401);return Map.of("code",401,"msg","登录已失效或已在其他设备登录","data",Map.of("valid",false));}
}
